coverage[-1]['finding']=coverage[-1]['finding'].replace('All28','All 28').replace('are578','are 578').replace(',579',', 579').replace(',604',', 604').replace('and605','and 605').replace('All24','All 24').replace('pages580','pages 580').replace('The23','The 23')
summary=dict(reviewerId=R,completedAt=now,questionsReviewed=99,verified=len(verified),flagged=len(flags),criterionFindings=sum(map(len,flags.values())),keyDisagreements=0,actualPagesInspected=28,reviewFile=out,reviewSha256=sha(out),blindAnswersSha256=sha(ap),independentChecks='audits/W04-L19-independent-checks.json',flaggedQuestionIds=list(flags),findings=[{'questionId':qid,'criteria':[k for k,_ in fs],'findings':[msg for _,msg in fs]} for qid,fs in flags.items()],coverageChallenge=coverage,validation=v,sourceQualifications='Preserve all seven sourceIssues and independent source observations. No source uncertainty was silently resolved globally.',mutations='Only reviewer audit, check-script, review and handoff files. No question, canonical bank, source or Git edits.')
write('audits/W04-L19-contracts-review-summary.json',summary)
(ROOT/'docs/handoffs/L19-contracts-review.md').write_text(f'# L19 independent review frozen\n\n{len(verified)} verified and {len(flags)} flagged out of 99 questions, with zero key disagreements. All 28 actual pages 578–605 were personally inspected. Reviewer-owned checks passed 43 exact/symbolic assertions plus 500 random trials.\n\nReview: data/reviews/W04-L19-v1-independent-contracts.json. Exact item findings and coverage challenge: audits/W04-L19-contracts-review-summary.json. Independent answer freeze: audits/blind-answers-W04-L19-v1-contracts-reviewer.json, SHA256 {sha(ap)}. The keyed snapshot and reveal record preserve the order of access.\n\nDefinite repairs include missing independent-coordinate assumptions in P0580-Q02, missing pre-answer frame/attachment definitions in P0582-Q04, duplicated encoder/downstream-compliance reasoning in P0594-Q04, incomplete formula definitions, weak alternatives and direct-recognition items labelled medium. All intended keys matched the blind answers. Preserve the {len(verified)} accepted correctness hashes while revising only flagged objects.\n\nCoverage challenge: one full paired hollow-beam stiffness/deflection numerical angle remains; strengthen P0588-Q03 to assess the source-specific lead/ball-screw design tradeoff. All 24 substantive pages have citations, but citation count alone does not prove complete assessment. No author content, bank, sources or Git changed. Awaiting the next distinct assignment or authorized revision-review packet.\n')
print(json.dumps({k:summary[k] for k in ['verified','flagged','criterionFindings','reviewSha256','flaggedQuestionIds','validation']},indent=2))
